import {e,download} from '../ui.mjs';
import {vectorResult,printVectorPages,svgPNG} from './vector.mjs';
export function pageSVG(title,subtitle,body,{width=794,height=1123,footer='NEPOCORE · MAKE A LITTLE ROOM FOR YOUR IDEAS'}={}){return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${e(title)}"><title>${e(title)}</title><rect width="100%" height="100%" fill="white"/><g font-family="Arial,sans-serif" fill="#263c33"><text x="40" y="50" font-size="27" font-weight="700">${e(title)}</text><text x="40" y="79" font-size="12">${e(subtitle)}</text><path d="M40 100H${width-40}" stroke="#b5c6b9"/>${body}<path d="M40 ${height-45}H${width-40}" stroke="#d8e0da"/><text x="40" y="${height-24}" font-size="9" fill="#6c7d72">${e(footer)}</text></g></svg>`;}
export function svgTextLines(value,max=42){const lines=[];let line='';for(let word of String(value).split(/\s+/)){while(Array.from(word).length>max){if(line){lines.push(line);line='';}lines.push(Array.from(word).slice(0,max).join(''));word=Array.from(word).slice(max).join('');}if((line+' '+word).trim().length>max&&line){lines.push(line);line=word;}else line+=(line?' ':'')+word;}if(line)lines.push(line);return lines;}
export function pagesResult(out,pages,name,{paper='a4',width=794,height=1123,details=[],note='',labels=[]}={}){vectorResult(out,pages[0],name,{width:width*2,height:height*2,details:[['Pages',pages.length],...details],note});printVectorPages(out,pages,paper,name+'.pdf');pages.slice(1).forEach((svg,i)=>{const wrap=document.createElement('details');wrap.className='worksheet-key';wrap.innerHTML='<summary>'+e(labels[i]||'Additional page '+(i+2))+'</summary><div class="vector-preview">'+svg+'</div><div class="result-actions"><button type="button" class="btn secondary small" data-extra-png>Download page '+(i+2)+' PNG</button><button type="button" class="btn secondary small" data-extra-svg>Download page '+(i+2)+' SVG</button></div>';out.append(wrap);wrap.querySelector('[data-extra-svg]').onclick=()=>download(new Blob([svg],{type:'image/svg+xml'}),name+'-page-'+(i+2)+'.svg');wrap.querySelector('[data-extra-png]').onclick=async ev=>{const b=ev.currentTarget;b.disabled=true;try{const blob=await svgPNG(svg,width*2,height*2);if(b.isConnected)download(blob,name+'-page-'+(i+2)+'.png');}finally{if(b.isConnected)b.disabled=false;}};});}
